00063 void  Reshape::createDec(int bitDepth)
00064 {
00065   m_lumaBD = bitDepth;
00066   m_reshapeLUTSize = 1 << m_lumaBD;
00067   m_initCW = m_reshapeLUTSize / PIC_CODE_CW_BINS;
00068   if (m_fwdLUT.empty())
00069     m_fwdLUT.resize(m_reshapeLUTSize, 0);
00070   if (m_invLUT.empty())
00071     m_invLUT.resize(m_reshapeLUTSize, 0);
00072   if (m_binCW.empty())
00073     m_binCW.resize(PIC_CODE_CW_BINS, 0);
00074   if (m_inputPivot.empty())
00075     m_inputPivot.resize(PIC_CODE_CW_BINS + 1, 0);
00076   if (m_fwdScaleCoef.empty())
00077     m_fwdScaleCoef.resize(PIC_CODE_CW_BINS, 1 << FP_PREC);
00078   if (m_invScaleCoef.empty())
00079     m_invScaleCoef.resize(PIC_CODE_CW_BINS, 1 << FP_PREC);
00080   if (m_reshapePivot.empty())
00081     m_reshapePivot.resize(PIC_CODE_CW_BINS + 1, 0);
00082   if (m_chromaAdjHelpLUT.empty())
00083     m_chromaAdjHelpLUT.resize(PIC_CODE_CW_BINS, 1<<CSCALE_FP_PREC);
00084 }
