00096 int  Reshape::calculateChromaAdj(Pel avgLuma)
00097 {
00098   int iAdj = m_chromaAdjHelpLUT[getPWLIdxInv(avgLuma)];
00099   return(iAdj);
00100 }
00101 
00106 int  Reshape::calculateChromaAdjVpduNei(TransformUnit &tu, const CompArea &areaY)
00107 {
00108   CodingStructure &cs = *tu.cs;
00109   int xPos = areaY.lumaPos().x;
00110   int yPos = areaY.lumaPos().y;
00111   int ctuSize = cs.sps->getCTUSize();
00112   int numNeighbor = std::min(64, ctuSize);
00113   int numNeighborLog = floorLog2(numNeighbor);
00114   if (ctuSize == 128)
00115   {
00116     xPos = xPos / 64 * 64;
00117     yPos = yPos / 64 * 64;
00118   }
00119   else
00120   {
00121     xPos = xPos / ctuSize * ctuSize;
00122     yPos = yPos / ctuSize * ctuSize;
00123   }
00124 
00125   if (isVPDUprocessed(xPos, yPos) && !cs.pcv->isEncoder)
00126   {
00127     return getChromaScale();
00128   }
00129   else
00130   {
00131     setVPDULoc(xPos, yPos);
00132     Position topLeft(xPos, yPos);
00133     CodingUnit *topLeftLuma;
00134     const CodingUnit *cuAbove, *cuLeft;
00135     if (CS::isDualITree(cs) && cs.slice->getSliceType() == I_SLICE)
00136     {
00137       topLeftLuma = tu.cs->picture->cs->getCU(topLeft, CHANNEL_TYPE_LUMA);
00138       cuAbove = cs.picture->cs->getCURestricted(topLeftLuma->lumaPos().offset(0, -1), *topLeftLuma, CHANNEL_TYPE_LUMA);
00139       cuLeft  = cs.picture->cs->getCURestricted(topLeftLuma->lumaPos().offset(-1, 0), *topLeftLuma, CHANNEL_TYPE_LUMA);
00140     }
00141     else
00142     {
00143       topLeftLuma = cs.getCU(topLeft, CHANNEL_TYPE_LUMA);
00144       cuAbove = cs.getCURestricted(topLeftLuma->lumaPos().offset(0, -1), *topLeftLuma, CHANNEL_TYPE_LUMA);
00145       cuLeft  = cs.getCURestricted(topLeftLuma->lumaPos().offset(-1, 0), *topLeftLuma, CHANNEL_TYPE_LUMA);
00146     }
00147 
00148     xPos = topLeftLuma->lumaPos().x;
00149     yPos = topLeftLuma->lumaPos().y;
00150 
00151     CompArea lumaArea = CompArea(COMPONENT_Y, tu.chromaFormat, topLeftLuma->lumaPos(), topLeftLuma->lumaSize(), true);
00152     PelBuf piRecoY = cs.picture->getRecoBuf(lumaArea);
00153     int strideY = piRecoY.stride;
00154     int chromaScale = (1 << CSCALE_FP_PREC);
00155     int lumaValue = -1;
00156 
00157     Pel* recSrc0 = piRecoY.bufAt(0, 0);
00158     const uint32_t picH = tu.cs->picture->lheight();
00159     const uint32_t picW = tu.cs->picture->lwidth();
00160     const Pel   valueDC = 1 << (tu.cs->sps->getBitDepth(CHANNEL_TYPE_LUMA) - 1);
00161     int32_t recLuma = 0;
00162     int pelnum = 0;
00163     if (cuLeft != nullptr)
00164     {
00165       for (int i = 0; i < numNeighbor; i++)
00166       {
00167         int k = (yPos + i) >= picH ? (picH - yPos - 1) : i;
00168         recLuma += recSrc0[-1 + k * strideY];
00169         pelnum++;
00170       }
00171     }
00172     if (cuAbove != nullptr)
00173     {
00174       for (int i = 0; i < numNeighbor; i++)
00175       {
00176         int k = (xPos + i) >= picW ? (picW - xPos - 1) : i;
00177         recLuma += recSrc0[-strideY + k];
00178         pelnum++;
00179       }
00180     }
00181     if (pelnum == numNeighbor)
00182     {
00183       lumaValue = (recLuma + (1 << (numNeighborLog - 1))) >> numNeighborLog;
00184     }
00185     else if (pelnum == (numNeighbor << 1))
00186     {
00187       lumaValue = (recLuma + (1 << numNeighborLog)) >> (numNeighborLog + 1);
00188     }
00189     else
00190     {
00191       CHECK(pelnum != 0, "");
00192       lumaValue = valueDC;
00193     }
00194     chromaScale = calculateChromaAdj(lumaValue);
00195     setChromaScale(chromaScale);
00196     return(chromaScale);
00197   }
00198 }
00203 int Reshape::getPWLIdxInv(int lumaVal)
00204 {
00205   int idxS = 0;
00206   for (idxS = m_sliceReshapeInfo.reshaperModelMinBinIdx; (idxS <= m_sliceReshapeInfo.reshaperModelMaxBinIdx); idxS++)
00207   {
00208     if (lumaVal < m_reshapePivot[idxS + 1])     break;
00209   }
00210   return std::min(idxS, PIC_CODE_CW_BINS-1);
00211 }
00212 
00218 void Reshape::copySliceReshaperInfo(SliceReshapeInfo& tInfo, SliceReshapeInfo& sInfo)
00219 {
00220   tInfo.sliceReshaperModelPresentFlag = sInfo.sliceReshaperModelPresentFlag;
00221   if (sInfo.sliceReshaperModelPresentFlag)
00222   {
00223     tInfo.reshaperModelMaxBinIdx = sInfo.reshaperModelMaxBinIdx;
00224     tInfo.reshaperModelMinBinIdx = sInfo.reshaperModelMinBinIdx;
00225     memcpy(tInfo.reshaperModelBinCWDelta, sInfo.reshaperModelBinCWDelta, sizeof(int)*(PIC_CODE_CW_BINS));
00226     tInfo.maxNbitsNeededDeltaCW = sInfo.maxNbitsNeededDeltaCW;
00227     tInfo.chrResScalingOffset = sInfo.chrResScalingOffset;
00228   }
00229   tInfo.sliceReshaperEnableFlag = sInfo.sliceReshaperEnableFlag;
00230   if (sInfo.sliceReshaperEnableFlag)
00231     tInfo.enableChromaAdj = sInfo.enableChromaAdj;
00232   else
00233     tInfo.enableChromaAdj = 0;
00234 }
00235 
00240 void Reshape::constructReshaper()
00241 {
00242   int pwlFwdLUTsize = PIC_CODE_CW_BINS;
00243   int pwlFwdBinLen = m_reshapeLUTSize / PIC_CODE_CW_BINS;
00244 
00245   for (int i = 0; i < m_sliceReshapeInfo.reshaperModelMinBinIdx; i++)
00246     m_binCW[i] = 0;
00247   for (int i = m_sliceReshapeInfo.reshaperModelMaxBinIdx + 1; i < PIC_CODE_CW_BINS; i++)
00248     m_binCW[i] = 0;
00249   for (int i = m_sliceReshapeInfo.reshaperModelMinBinIdx; i <= m_sliceReshapeInfo.reshaperModelMaxBinIdx; i++)
00250     m_binCW[i] = (uint16_t)(m_sliceReshapeInfo.reshaperModelBinCWDelta[i] + (int)m_initCW);
00251 
00252   for (int i = 0; i < pwlFwdLUTsize; i++)
00253   {
00254     m_reshapePivot[i + 1] = m_reshapePivot[i] + m_binCW[i];
00255     m_inputPivot[i + 1] = m_inputPivot[i] + m_initCW;
00256     m_fwdScaleCoef[i] = ((int32_t)m_binCW[i] * (1 << FP_PREC) + (1 << (floorLog2(pwlFwdBinLen) - 1))) >> floorLog2(pwlFwdBinLen);
00257     if (m_binCW[i] == 0)
00258     {
00259       m_invScaleCoef[i] = 0;
00260       m_chromaAdjHelpLUT[i] = 1 << CSCALE_FP_PREC;
00261     }
00262     else
00263     {
00264       m_invScaleCoef[i] = (int32_t)(m_initCW * (1 << FP_PREC) / m_binCW[i]);
00265       m_chromaAdjHelpLUT[i] = (int32_t)(m_initCW * (1 << FP_PREC) / ( m_binCW[i] + m_sliceReshapeInfo.chrResScalingOffset ) );
00266     }
00267   }
00268   for (int lumaSample = 0; lumaSample < m_reshapeLUTSize; lumaSample++)
00269   {
00270     int idxY = lumaSample / m_initCW;
00271     int tempVal = m_reshapePivot[idxY] + ((m_fwdScaleCoef[idxY] * (lumaSample - m_inputPivot[idxY]) + (1 << (FP_PREC - 1))) >> FP_PREC);
00272     m_fwdLUT[lumaSample] = Clip3((Pel)0, (Pel)((1 << m_lumaBD) - 1), (Pel)(tempVal));
00273 
00274     int idxYInv = getPWLIdxInv(lumaSample);
00275     int invSample = m_inputPivot[idxYInv] + ((m_invScaleCoef[idxYInv] * (lumaSample - m_reshapePivot[idxYInv]) + (1 << (FP_PREC - 1))) >> FP_PREC);
00276     m_invLUT[lumaSample] = Clip3((Pel)0, (Pel)((1 << m_lumaBD) - 1), (Pel)(invSample));
00277   }
00278 }
